export const BUKLOD_HYMNS: BuklodHymn[] = [{"id":"hymn-001","number":1,"title":"THIS WORLD IS NOT MY HOME","subtitle":null,"lyrics":"This world is not my home, I'm just a passing through\nMy treasures are laid up somewhere beyond the blue;\nThe angels beckon me from heaven's open door,\nAnd I can't feel at home in this world anymore.\n\nChorus:\nO Lord, you know I have no friend like you,\nIf heaven's not my home, then Lord what will I do?\nThe angels beckon me from heaven's open door,\nAnd I can't feel at home in this world anymore.\n\nThey're all expecting me, and that's one thing I know,\nMy Savior pardoned me and now I onward go;\nI know He'll take me thro' tho' I am weak and poor,\nAnd I can't feel at home in this world anymore.\n\nI have a loving Savior up in glory-land,\nI don't expect to stop until I with Him stand,\nHe's waiting now for me in heaven's open door,\nAnd I can't feel at home in this world anymore.\n\nJust up in glory-land we'll live eternally,\nThe saints on every hand are shouting victory,\nTheir songs of sweetest praise drift back from heaven's\nshore,\nAnd I can't feel at home in this world anymore.","sourcePage":1},{"id":"hymn-002","number":2,"title":"ONWARD CHRISTIAN SOLDIERS","subtitle":null,"lyrics":"Onward, Christian soldiers, marching as to war,\nWith the cross of Jesus going on before!\nChrist, the royal Master, leads against the foe;\nForward into battle, see his banner go!\n\nRefrain:\nOnward, Christian soldiers, marching as to war,\nWith the cross of Jesus going on before!\nAt the sign of triumph Satan's host doth flee;\nOn, then, Christian soldiers, on to victory!\n\nHell's foundations quiver at the shout of praise;\nBrothers, lift your voices, loud your anthems\nraise!\nLike a mighty army moves the church of God;\nBrothers, we are treading where the saints have\ntrod;\nWe are not divided; all one body we,\nOne in hope and doctrine, one in charity.\n\nOnward, then, ye people, join our happy throng,\nBlend with ours your voices in the triumph song;\nGlory, laud, and honor, unto Christ the King;\nThis thro' countless ages men and angels sing.","sourcePage":2},{"id":"hymn-003","number":3,"title":"THE LILY OF THE VALLEY","subtitle":null,"lyrics":"I've found a friend in Jesus, He's everything to me\nHe's the fairest of ten thousand to my soul\nThe Lily of the Valley, in Him alone I see\nAll I need to cleanse and make me fully whole\n\nIn sorrow He's my comfort, in trouble He's my stay\nHe tells me every care on Him to roll\nHe's the Lily of the Valley, the Bright and Morning Star\nHe's the fairest of ten thousand to my soul\n\nOh, He all my grief has taken, and all my sorrows borne\nIn temptation, He's my strong and mighty tow'r\nI have all for Him forsaken and all my idols torn\nFrom my heart and now He keeps me by His pow'r\n\nThough all the world forsake me and Satan tempt me\nsore\nThrough Jesus, I shall safely reach the goal\nHe's the Lily of the Valley, the Bright and Morning Star\nHe's the fairest of ten thousand to my soul\n\nHe will never, never leave me, nor yet forsake me here\nWhile I live by faith and do His blessed will\nA wall of fire about me, I've nothing now to fear\nWith His manna, He my hungry soul shall fill\n\nThen sweeping up to glory to see His blessed face\nWhere rivers of delight shall ever roll\nHe's the Lily of the Valley, the Bright and Morning Star\nHe's the fairest of ten thousand to my soul","sourcePage":3},{"id":"hymn-004","number":4,"title":"WHEN WE ALL GET TO HEAVEN","subtitle":null,"lyrics":"Sing the wondrous love of Jesus,\nSing His mercy and His grace;\nIn the mansions bright and blessed\nHe'll prepare for us a place.\n\nRefrain:\nWhen we all get to heaven,\nwhat a day of rejoicing that will be!\nWhen we all see Jesus,\nwe'll sing and shout the victory!\n\nWhile we walk the pilgrim pathway\nClouds will overspread the sky;\nBut when trav'ling days are over\nNot a shadow, not a sigh. [Refrain]\n\nLet us then be true and faithful,\nTrusting, serving ev'ry day;\nJust one glimpse of Him in glory\nWill the toils of life repay. [Refrain]\n\nOnward to the prize before us!\nSoon His beauty we'll behold;\nSoon the pearly gates will open–\nWe shall tread the streets of gold.","sourcePage":4},{"id":"hymn-005","number":5,"title":"ALL HAIL THE POWER OF JESUS","subtitle":null,"lyrics":"1 All hail the power of Jesus' name!\nLet angels prostrate fall.\nBring forth the royal diadem,\nand crown him Lord of all.\nBring forth the royal diadem,\nand crown him Lord of all!\n\n2 O seed of Israel's chosen race\nnow ransomed from the fall,\nhail him who saves you by his grace,\nand crown him Lord of all.\nHail him who saves you by his grace,\nand crown him Lord of all!\n\n3 Let every tongue and every tribe\nresponsive to his call,\nto him all majesty ascribe,\nand crown him Lord of all.\nTo him all majesty ascribe,\nand crown him Lord of all!\n\n4 Oh, that with all the sacred throng\nwe at his feet may fall!\nWe'll join the everlasting song\nand crown him Lord of all.\nWe'll join the everlasting song\nand crown him Lord of all.","sourcePage":5},{"id":"hymn-006","number":6,"title":"KEEP ON THE FIRING LINE","subtitle":null,"lyrics":"1. If you’re in the battle for the Lord and right,\nKeep on the firing line;\nIf you win, my brother, surely you must fight,\nKeep on the firing line.\nThere are many dangers that we all must face,\nIf we die still fighting it is no disgrace;\nCowards in the service will not find a place,\nSo keep on the firing line.\n\nRefrain:\nOh, you must fight, be brave against all evil,\nNever run, nor even lag behind;\nIf you would win for God and the right,\nJust keep on the firing line.\n\n2. God will only use the soldier He can trust,\nKeep on the firing line;\nIf you’ll wear a crown then bear the cross you must,\nKeep on the firing line.\nLife is but to labor for the Master dear,\nHelp to banish evil and to spread good cheer;\nGreat you’ll be rewarded for your service here,\nSo keep on the firing line.\n\n3. When we get to heaven, brother, we’ll be glad,\nKeep on the firing line;\nHow we’ll praise the Savior for the call we had,\nKeep on the firing line.\nWhen we see the souls that we have helped to win,\nLeading them to Jesus, from the paths of sin,\nWith a shout of welcome, we will all march in,\nSo keep on the firing line.","sourcePage":6},{"id":"hymn-007","number":7,"title":"WONDERFUL GRACE OF JESUS","subtitle":null,"lyrics":"Wonderful Grace of Jesus, greater than all my sin;\nHow shall my tongue describe it,\nWhere shall its praise begin?\nTaking away my burden, setting my spirit free;\nO the Wonderful Grace of Jesus reaches me!\n\nRefrain\nWonderful the matchless Grace of Jesus,\nthe matchless Grace of Jesus,\nDeeper than the mighty rolling sea;\nthe rolling sea;\nWonderful Grace, all sufficient for me, for even\nHigher than the mountain, sparkling like a fountain,\nAll sufficient Grace for even me.\nBroader than the scope of my transgressions,\nsing it!\nGreater far than all my sin and shame\nmy sin and shame,\nO magnify the precious name of Jesus,\nPRAISE HIS NAME!\n\nWonderful Grace of Jesus, reaching to all the lost;\nBy it I have been pardoned, saved to the uttermost.\nChains have been torn asunder, giving me liberty;\nO the Wonderful Grace of Jesus, reaches me! [Refrain]\n\nWonderful Grace of Jesus, reaching the most defiled;\nBy its transforming power,\nMaking me God's dear child,\nPurchasing peace and Heaven, for all eternity;\nAnd the Wonderful Grace of Jesus, reaches me! [Refrain]","sourcePage":7},{"id":"hymn-008","number":8,"title":"STANDING ON THE PROMISES","subtitle":null,"lyrics":"1 Standing on the promises of Christ, my King,\nThrough eternal ages let his praises ring;\nGlory in the highest, I will shout and sing,\nStanding on the promises of God.\n\nRefrain:\nStanding, standing,\nStanding on the promises of God, my Savior;\nStanding, standing,\nI'm standing on the promises of God.\n\n2 Standing on the promises that cannot fail.\nWhen the howling storms of doubt and fear\nassail,\nBy the living Word of God I shall prevail,\nStanding on the promises of God. [Refrain]\n\n3 Standing on the promises of Christ, the Lord,\nBound to him eternally by love's strong cord,\nOvercoming daily with the Spirit's sword,\nStanding on the promises of God. [Refrain]\n\n4 Standing on the promises I cannot fall,\nList'ning ev'ry moment to the Spirit's call,\nResting in my Savior as my all in all,\nStanding on the promises of God. [Refrain]","sourcePage":8},{"id":"hymn-009","number":9,"title":"BRINGING IN THE SHEAVES","subtitle":null,"lyrics":"1 Sowing in the morning, sowing seeds of kindness,\nSowing in the noontide and the dewy eve;\nWaiting for the harvest, and the time of reaping,\nWe shall come rejoicing, bringing in the sheaves.\n\nRefrain:\nBringing in the sheaves,\nBringing in the sheaves,\nWe shall come rejoicing, bringing in the sheaves;\nBringing in the sheaves,\nBringing in the sheaves,\nWe shall come rejoicing, bringing in the sheaves.\n\n2 Sowing in the sunshine, sowing in the shadows,\nFearing neither clouds nor winter's chilling breeze;\nBy and by the harvest, and the labor ended,\nWe shall come rejoicing, bringing in the sheaves.\n[Refrain]\n\n3 Going forth with weeping, sowing for the Master,\nThough the loss sustained our spirit often grieves;\nWhen our weeping's over, He will bid us welcome,\nWe shall come rejoicing, bringing in the sheaves.\n[Refrain]","sourcePage":9},{"id":"hymn-010","number":10,"title":"TRUST AND OBEY","subtitle":null,"lyrics":"1 When we walk with the Lord\nin the light of his word,\nwhat a glory he sheds on our way!\nWhile we do his good will,\nhe abides with us still,\nand with all who will trust and obey.\n\nRefrain:\nTrust and obey, for there's no other way\nto be happy in Jesus, but to trust and obey.\n\n2 Not a burden we bear,\nnot a sorrow we share,\nbut our toil he doth richly repay;\nnot a grief or a loss,\nnot a frown or a cross,\nbut is blest if we trust and obey. [Refrain]\n\n3 But we never can prove\nthe delights of his love\nuntil all on the altar we lay;\nfor the favor he shows,\nfor the joy he bestows,\nare for them who will trust and obey. [Refrain]\n\n4 Then in fellowship sweet\nwe will sit at his feet,\nor we'll walk by his side in the way;\nwhat he says we will do,\nwhere he sends we will go;\nnever fear, only trust and obey. [Refrain]","sourcePage":10},{"id":"hymn-011","number":11,"title":"BECAUSE HE LIVES","subtitle":null,"lyrics":"God sent His son, they called Him, Jesus;\nHe came to love, heal and forgive;\nHe lived and died to buy my pardon,\nAn empty grave is there to prove my\nSavior lives!\n\nBecause He lives, I can face tomorrow,\nBecause He lives, all fear is gone;\nBecause I know He holds the future,\nAnd life is worth the living,\nJust because He lives!\n\nHow sweet to hold a newborn baby,\nAnd feel the pride and joy he brings;\nBut greater still the calm assurance:\nThis child can face uncertain days because\nHe Lives!\n\nAnd then one day, I'll cross the river,\nI'll fight life's final war with pain;\nAnd then, as death gives way to victory,\nI'll see the lights of glory and I'll know He\nlives!","sourcePage":11},{"id":"hymn-012","number":12,"title":"STILL SWEETER EVERYDAY","subtitle":null,"lyrics":"1 To Jesus ev'ry day I find my heart is closer drawn,\nHe's fairer than the glory of the gold and purple dawn;\nHe's all my fancy pictures in its fairest dreams, and\nmore,\nEach day He grows still sweeter than He was the day\nbefore.\n\nRefrain:\nThe half cannot be fancied, this side the golden shore;\nO there He'll be still sweeter than He ever was before.\n\n2 His glory broke upon me when I saw Him from afar,\nHe's fairer than the lily, brighter than the morning star;\nHe fills and satisfies my longing spirit o'er and o'er,\nEach day He grows still sweeter than He was the day\nbefore. [Refrain]\n\n3 My heart is sometimes heavy but he comes with sweet\nrelief,\nHe folds me to His bosom when I droop with blighting\ngrief;\nI love the Christ who all my burdens in His body bore,\nEach day He grows still sweeter than He was the day\nbefore. [Refrain]","sourcePage":12},{"id":"hymn-013","number":13,"title":"THERE’S POWER IN THE BLOOD","subtitle":null,"lyrics":"1 Would you be free from the burden of sin?\nThere's pow'r in the blood, pow'r in the blood;\nWould you o'er evil a victory win?\nThere's wonderful pow'r in the blood.\n\nRefrain:\nThere is pow'r, pow'r, wonder-working pow'r\nIn the blood of the Lamb;\nThere is pow'r, pow'r, wonder-working pow'r\nIn the precious blood of the Lamb.\n\n2 Would you be free from your passion and\npride?\nThere's pow'r in the blood, pow'r in the blood;\nCome for a cleansing to Calvary's tide–\nThere's wonderful pow'r in the blood. [Refrain]\n\n3 Would you be whiter, yes brighter than snow?\nThere's pow'r in the blood, pow'r in the blood;\nSin-stains are lost in its life-giving flow–\nThere's wonderful pow'r in the blood. [Refrain]\n\n4 Would you do service for Jesus, your King?\nThere's pow'r in the blood, pow'r in the blood;\nWould you live daily His praises to sing?\nThere's wonderful pow'r in the blood. [Refrain]","sourcePage":13},{"id":"hymn-014","number":14,"title":"MY SAVIOR’S LOVE","subtitle":null,"lyrics":"1. I stand amazed in the presence\nOf Jesus the Nazarene,\nAnd wonder how he could love me,\nA sinner, condemned, unclean.\n\nRefrain:\nHow marvelous! How wonderful!\nAnd my song shall ever be:\nHow marvelous! How wonderful\nIs my Savior’s love for me.\n\n2. For me it was in the garden\nHe prayed, “Not my will, but thine.”\nHe had no tears for his own griefs,\nBut sweat drops of blood for mine.\n\n3. In pity, angels beheld him,\nAnd came from the world of light\nTo comfort him in the sorrows\nHe bore for my soul that night.\n\n4. He took my sins and my sorrows,\nHe made them his very own;\nHe bore the burden to Calv’ry,\nAnd suffered, and died alone.","sourcePage":14},{"id":"hymn-015","number":15,"title":"BATTLE HYMN OF TH REPUBLIC","subtitle":null,"lyrics":"1 Mine eyes have seen the glory of the coming of the Lord;\nHe is trampling out the vintage where the grapes of wrath are\nstored;\nHe hath loosed the fateful lightning of his terrible swift sword:\nHis truth is marching on.\n\nRefrain:\nGlory! Glory! Hallelujah!\nGlory! Glory! Hallelujah!\nGlory! Glory! Hallelujah!\nHis truth is marching on.\n\n2 I have seen him in the watch-fires of a hundred circling\ncamps;\nThey have builded him an altar in the evening dews and\ndamps;\nI can read the righteous sentence by the dim and flaring\nlamps;\nHis day is marching on. [Refrain]\n\n3 He has sounded forth the trumpet that shall never call\nretreat;\nHe is sifting out the hearts of all before his judgment seat;\nO be swift, my soul, to answer him; be jubilant, my feet!\nOur God is marching on. [Refrain]\n\n4 In the beauty of the lilies Christ was born across the sea,\nWith a glory in his bosom that transfigures you and me;\nAs he died to make us holy, let us die that all be free!\nWhile God is marching on. [Refrain]","sourcePage":15},{"id":"hymn-016","number":16,"title":"COME THOU FOUNT","subtitle":null,"lyrics":"1 Come, thou Fount of every blessing;\ntune my heart to sing thy grace;\nstreams of mercy, never ceasing,\ncall for songs of loudest praise.\nTeach me some melodious sonnet,\nsung by flaming tongues above;\npraise the mount! I’m fixed upon it,\nmount of God’s unchanging love!\n\n2 O to grace how great a debtor\ndaily I’m constrained to be!\nLet that grace now, like a fetter,\nbind my wandering heart to thee.\nJesus sought me when a stranger,\nwandering from the fold of God;\nhe, to rescue me from danger,\ninterposed his precious blood.\n\n3 Prone to wander, Lord, I feel it;\nProne to leave the God I love:\nTake my heart, oh, take and seal it\nWith Thy Spirit from above.\nRescued thus from sin and danger,\nPurchased by the Savior’s blood,\nMay I walk on earth a stranger,\nAs a son and heir of God.","sourcePage":16},{"id":"hymn-017","number":17,"title":"WHEN THE ROLL IS CALLED UP YONDER","subtitle":null,"lyrics":"1 When the trumpet of the Lord shall sound and time\nshall be no more,\nAnd the morning breaks, eternal, bright and fair;\nWhen the saved of earth shall gather over on the other\nshore,\nAnd the roll is called up yonder, I'll be there.\n\nRefrain:\nWhen the roll is called up yonder,\nWhen the roll is called up yonder,\nWhen the roll is called up yonder,\nWhen the roll is called up yonder, I'll be there.\n\n2 On that bright and cloudless morning when the dead in\nChrist shall rise,\nAnd the glory of his resurrection share;\nWhen his chosen ones shall gather to their home beyond\nthe skies,\nAnd the roll is called up yonder, I'll be there. [Refrain]\n\n3 Let us labor for the Master from the dawn till setting\nsun;\nLet us talk of all his wondrous love and care.\nThen when all of life is over and our work on earth is\ndone,\nAnd the roll is called up yonder, I'll be there. [Refrain]","sourcePage":17},{"id":"hymn-018","number":18,"title":"VICTORY IN JESUS","subtitle":null,"lyrics":"I heard an old, old story, how a Savior came from glory\nHow He gave His life on Calvary to save a wretch like me\nI heard about His groaning, of His precious blood's atoning\nThen I repented of my sins, and won the victory, yeah\n\nChorus:\nOh, victory in Jesus, my Savior forever\nHe sought me and bought me with His redeeming blood\nHe loved me 'ere I knew Him and all my love is due Him\nHe plunged me to victory beneath the cleansing flood\n\nI heard about His healing, of His cleansing power revealing\nHow He made the lame to walk again and 'caused the blind to\nsee\nAnd then I cried, \"Dear Jesus, come and heal my broken\nspirit\"\nAnd somehow Jesus came and brought to me the victory\n\nVictory in Jesus, my Savior forever\nHe sought me and He bought me with His redeeming blood\nHe loved me 'ere I knew Him and all my love is due Him\nHe plunged me to victory beneath the cleansing flood, oh\n\nYes, victory in Jesus, my Savior forever\nHe sought me and He bought me with His redeeming blood\nHe loved me 'ere I knew Him and all my love is due Him\nHe plunged me to victory beneath the cleansing flood\nYes, he plunged me to victory beneath the cleansing flood","sourcePage":18},{"id":"hymn-019","number":19,"title":"TO GOD BE THE GLORY","subtitle":null,"lyrics":"To God be the glory, great things He hath done,\nSo loved He the world that He gave us His Son,\nWho yielded His life our redemption to win,\nAnd opened the life-gate that all may go in.\n\nChorus:\nPraise the Lord, praise the Lord,\nLet the earth hear His voice;\nPraise the Lord, praise the Lord,\nLet the people rejoice;\nOh, come to the Father, through Jesus the Son,\nAnd give Him the glory; great things He hath\ndone.\n\nOh, perfect redemption, the purchase of blood,\nTo every believer the promise of God;\nThe vilest offender who truly believes,\nThat moment from Jesus a pardon receives.\n\nGreat things He hath taught us, great things He\nhath done,\nAnd great our rejoicing through Jesus the Son;\nBut purer, and higher, and greater will be\nOur wonder, our transport when Jesus we see.","sourcePage":19},{"id":"hymn-020","number":20,"title":"A SHELTER IN THE TIME OF STORM","subtitle":null,"lyrics":"1 The Lord's our rock, in Him we hide,\nA shelter in the time of storm;\nSecure whatever ill betide,\nA shelter in the time of storm.\n\nRefrain:\nOh Jesus is a rock in a weary land,\nA weary land, a weary Land (2x)\nA Shelter in the time of Storm\n\n2 A shade by day, defense by night,\nA shelter in the time of storm;\nNo fears alarm, no fears affright,\n(Refrain)\n\n3 The raging storms may round us beat,\nA shelter in the time of storm;\nWe'll never leave our safe retreat,\nA shelter in the time of storm.\n(Refrain)\n\n4 O Rock divine, O Refuge dear,\nA shelter in the time of storm;\nBe Thou our helper ever near,\nA shelter in the time of storm.\n(Refrain)","sourcePage":20},{"id":"hymn-021","number":21,"title":"GLORY TO HIS NAME","subtitle":null,"lyrics":"1 Down at the cross where my Savior died,\nDown where for cleansing from sin I cried,\nThere to my heart was the blood applied;\nGlory to his name!\n\nRefrain:\nGlory to his name,\nGlory to his name;\nThere to my heart was the blood applied;\nGlory to his name!\n\n2 I am so wondrously saved from sin,\nJesus so sweetly abides within;\nThere at the cross where he took me in;\nGlory to his name! [Refrain]\n\n3 Oh, precious fountain that saves from sin,\nI am so glad I have entered in;\nThere Jesus saves me and keeps me clean;\nGlory to his name! [Refrain]\n\n4 Come to this fountain so rich and sweet,\nCast thy poor soul at the Savior’s feet;\nPlunge in today, and be made complete;\nGlory to his name! [Refrain]","sourcePage":21},{"id":"hymn-022","number":22,"title":"GREAT IS THY FAITHFULNESS","subtitle":null,"lyrics":"1. Great is thy faithfulness, O God, my Father;\nThere is no shadow of turning with thee.\nThou changest not, thy compassions, they\nfail not;\nAs thou hast been, thou forever wilt be.\n\nRefrain:\nGreat is thy faithfulness,\nGreat is thy faithfulness,\nMorning by morning new mercies I see.\nAll I have needed thy hand hast provided;\nGreat is thy faithfulness,\nLord unto me.\n\n2. Summer and winter and springtime and\nharvest,\nSun, moon, and stars in their courses above\nJoin with all nature in manifold witness\nTo thy great faithfulness, mercy, and love.\n[Refrain]\n\n3. Pardon for sin and a peace that endureth,\nThine own dear presence to cheer and to guide;\nStrength for today and bright hope for tomorrow,\nBlessings all mine and ten thousand beside.\n[Refrain]","sourcePage":22},{"id":"hymn-023","number":23,"title":"I KNOW WHOM I HAVE BELIEVED","subtitle":null,"lyrics":"I know not why God’s wondrous grace\nTo me He hath made known,\nNor why, unworthy, Christ in love\nRedeemed me for His own. [Refrain]\n\nRefrain:\nBut I know Whom I have believed,\nAnd am persuaded that He is able\nTo keep that which I’ve committed\nUnto Him against that day.\n\n2. I know not how this saving faith\nTo me He did impart,\nNor how believing in His Word\nWrought peace within my heart. [Refrain]\n\n3. I know not how the Spirit moves,\nConvincing us of sin,\nRevealing Jesus through the Word,\nCreating faith in Him. [Refrain]\n\n4. I know not when my Lord may come,\nAt night or noonday fair,\nNor if I walk the vale with Him,\nOr meet Him in the air. [Refrain]","sourcePage":23},{"id":"hymn-024","number":24,"title":"SINCE JESUS CAME INTO MY HEART","subtitle":null,"lyrics":"What a wonderful change in my life has been wrought\nSince Jesus came into my heart;\nI have light in my soul for which long I have sought,\nSince Jesus came into my heart.\n\nRefrain:\nSince Jesus came into my heart,\nSince Jesus came into my heart;\nFloods of joy o’er my soul like the sea billows roll,\nSince Jesus came into my heart.\n\nI have ceased from my wand’ring and going astray,\nSince Jesus came into my heart;\nAnd my sins which were many are all washed away,\nSince Jesus came into my heart.\n\nI’m possessed of a hope that is steadfast and sure,\nSince Jesus came into my heart;\nAnd no dark clouds of doubt now my pathway obscure,\nSince Jesus came into my heart.\n\nI shall go there to dwell in that City I know,\nSince Jesus came into my heart;\nAnd I’m happy, so happy as onward I go,\nSince Jesus came into my heart.","sourcePage":24},{"id":"hymn-025","number":25,"title":"FAITH IS THE VICTORY","subtitle":null,"lyrics":"Encamped along the hills of light, Ye Christian soldiers rise,\nAnd press the battle ere the night, Shall veil the glowing\nskies;\nAgainst the foe in vales below, Let all our strength be hurled;\nFaith is the victory, we know, That overcomes the world.\n\nChorus:\nFaith is the victory!\nFaith is the victory!\nO glorious victory,\nThat overcomes the world.\n\nHis banner over us is love, Our sword the Word of God;\nWe tread the road the saints before, With shouts of triumph\ntrod.\nBy faith, they like a whirlwind’s breath, on o’er every field;\nThe faith by which they conquered death still our shining\nshield.\n\nOn every hand the foe we find, up in dread array;\nLet tents of ease be left behind, onward to the fray.\nSalvation’s helmet on each head, With truth all girt about,\nThe earth shall tremble ’neath our tread, echo with our shout.\n\nTo him that overcomes the foe, White raiment shall be giv’n;\nBefore the angels he shall know, His name confessed in\nheav’n;\nThen onward from the hills of light, hearts with love aflame,\nWe’ll vanquish all the hosts of night, In Jesus’ conqu’ring\nname.","sourcePage":25},{"id":"hymn-026","number":26,"title":"THE BANNER OF THE CROSS","subtitle":null,"lyrics":"1 There's a royal banner given for display\nTo the soldiers of the King;\nAs an ensign fair we lift it up today,\nWhile as ransomed ones we sing.\n\nChorus:\nMarching on, marching on,\nFor Christ count ev'rything but loss!\nAnd to crown Him King,\ntoil and sing 'Neath the banner of the cross!\n\n2 Though the foe may rage and gather as the flood,\nLet the standard be displayed;\nAnd beneath its folds, as soldiers of the Lord,\nFor the truth be not dismayed!\n\n3 Over land and sea, wherever man may dwell,\nMake the glorious tidings known;\nOf the crimson banner now the story tell,\nWhile the Lord shall claim His own!\n\n4 When the glory dawns 'tis drawing very near--\nIt is hast'ning day by day;\nThen before our King the foe shall disappear,\nAnd the cross the world shall sway!","sourcePage":26},{"id":"hymn-027","number":27,"title":"I LOVE TO TELL THE STORY","subtitle":null,"lyrics":"I love to tell the story, Of unseen things above,\nOf Jesus and His glory, Jesus and His love.\nI love to tell the story, Because I know ’tis true;\nIt satisfies my longings, As nothing else can do.\n\nChorus:\nI love to tell the story,\n’Twill be my theme in glory\nTo tell the old, old story\nof Jesus and His love.\n\nI love to tell the story; More wonderful it seems\nThan all the golden fancies, Of all my golden dreams,\nI love to tell the story, It did so much for me;\nAnd that is just the reason, I tell it now to thee.\n\nI love to tell the story; ’Tis pleasant to repeat\nWhat seems each time I tell it, More wonderfully sweet.\nI love to tell the story; For some have never heard\nThe message of salvation, From God’s own holy Word.\n\nI love to tell the story; For those who know it best\nSeem hungering and thirsting, hear it like the rest.\nAnd when, in scenes of glory, I sing the new, new song,\n’Twill be the old, old story, That I have loved so long.","sourcePage":27},{"id":"hymn-028","number":28,"title":"AT THE CROSS","subtitle":null,"lyrics":"Alas! And did my Savior bleed\nAnd did my Sovereign die?\nWould He devote that sacred head\nFor such a worm as I?\n\nChorus:\nAt the cross, at the cross\nWhere I first saw the light,\nAnd the burden of my heart rolled away,\nIt was there by faith I received my sight,\nAnd now I am happy all the day!\n\nWas it for crimes that I had done\nHe groaned upon the tree?\nAmazing pity! Grace unknown!\nAnd love beyond degree!\n\nWell might the sun in darkness hide\nAnd shut his glories in,\nWhen Christ, the mighty Maker died,\nFor man the creature’s sin.\n\nThus might I hide my blushing face\nWhile His dear cross appears,\nDissolve my heart in thankfulness,\nAnd melt my eyes to tears.\n\nBut drops of grief can ne’er repay\nThe debt of love I owe:\nHere, Lord, I give myself away\n’Tis all that I can do.","sourcePage":28},{"id":"hymn-029","number":29,"title":"HARK THE HRALD ANGEL SING","subtitle":null,"lyrics":"1 Hark! the herald angels sing,\n\"Glory to the newborn King:\npeace on earth, and mercy mild,\nGod and sinners reconciled!\"\nJoyful, all ye nations, rise,\njoin the triumph of the skies;\nwith th'angelic hosts proclaim,\n\"Christ is born in Bethlehem!\"\n\nRefrain:\nHark! the herald angels sing,\n\"Glory to the newborn King\"\n\n2 Christ, by highest heaven adored,\nChrist, the everlasting Lord,\nlate in time behold him come,\noffspring of the Virgin's womb:\nveiled in flesh the Godhead see;\nhail th'incarnate Deity,\npleased with us in flesh to dwell,\nJesus, our Immanuel. [Refrain]\n\n3 Hail the heaven-born Prince of Peace!\nHail the Sun of Righteousness!\nLight and life to all he brings,\nrisen with healing in his wings.\nMild he lays his glory by,\nborn that we no more may die,\nborn to raise us from the earth,\nborn to give us second birth. [Refrain]","sourcePage":29},{"id":"hymn-030","number":30,"title":"O COME ALL YE FAITHFUL","subtitle":null,"lyrics":"1 O come, all ye faithful, joyful and triumphant,\nO come ye, O come ye to Bethlehem!\nCome, and behold Him, born the King of angels!\n\nRefrain:\nO come, let us adore Him;\nO come, let us adore Him;\nO come, let us adore Him, Christ, the Lord!\n2 God of God, Light of Light,\nlo, He abhors not the virgin's womb;\nvery God, begotten not created; [Refrain]\n\n3 Sing, choirs of angels; sing in exultation;\nsing, all ye citizens of heav'n above!\nGlory to God, all glory in the highest![Refrain]\n\n4 Yea, Lord, we greet Thee, born this happy\nmorning;\nJesus, to Thee be all glory giv'n!\nWord of the Father, now in flesh appearing!\n[Refrain]","sourcePage":30},{"id":"hymn-031","number":31,"title":"JOY TO THE WORLD","subtitle":null,"lyrics":"1. Joy to the world; the Lord is come;\nLet Earth receive her King;\nLet ev'ry heart prepare him room,\nAnd heav'n and nature sing.\n\n2. Joy to the Earth, the Savior reigns;\nOur mortal songs employ,\nWhile fields and floods, rocks, hills and\nplains,\nRepeat the sounding joy.\n3. No more let sins and sorrows grow,\nNor thorns infest the ground;\nHe comes to make his blessings flow\nFar as the curse is found.\n\n4. He rules the world with truth and grace,\nAnd makes the nations prove\nThe glories of his righteousness,\nAnd wonders of his love.","sourcePage":31},{"id":"hymn-032","number":32,"title":"WHAT A FRIEND WE HAVE IN JESUS","subtitle":null,"lyrics":"1 What a friend we have in Jesus,\nall our sins and griefs to bear!\nWhat a privilege to carry\neverything to God in prayer!\nO what peace we often forfeit,\nO what needless pain we bear,\nall because we do not carry\neverything to God in prayer!\n\n2 Have we trials and temptations?\nIs there trouble anywhere?\nWe should never be discouraged;\ntake it to the Lord in prayer!\nCan we find a friend so faithful\nwho will all our sorrows share?\nJesus knows our every weakness;\ntake it to the Lord in prayer!\n\n3 Are we weak and heavy laden,\ncumbered with a load of care?\nPrecious Savior, still our refuge--\ntake it to the Lord in prayer!\nDo your friends despise, forsake you?\nTake it to the Lord in prayer!\nIn his arms he'll take and shield you;\nyou will find a solace there.","sourcePage":32},{"id":"hymn-033","number":33,"title":"IN THE SWEET BY AND BY","subtitle":null,"lyrics":"1 There's a land that is fairer than day,\nAnd by faith we can see it afar,\nFor the Father waits over the way\nTo prepare us a dwelling place there.\n\nRefrain:\nIn the sweet by and by,\nWe shall meet on that beautiful shore;\nIn the sweet by and by,\nWe shall meet on that beautiful shore.\n\n2 We shall sing on that beautiful shore\nThe melodious songs of the blest;\nAnd our spirits shall sorrow no more-\nNot a sigh for the blessing of rest.\n\n3 To our bountiful Father above\nWe will offer our tribute of praise\nFor the glorious gift of His love\nAnd the blessings that hallow our days.","sourcePage":33},{"id":"hymn-034","number":34,"title":"SEND THE LIGHT","subtitle":null,"lyrics":"1 There's a call comes ringing o'er the restless\nwave, \"Send the light! Send the light\"\nThere are souls to rescue, there are souls to\nsave,\nSend the light! Send the light!\n\nChorus:\nSend the light, the blessed gospel light;\nLet it shine from shore to shore!\nSend the light the blessed gospel light;\nLet it shine forevermore!\n\n2 We have heard the Macedonian call\ntoday,\"Send the light! Send the light!\"\nAnd a golden off'ring at the cross we lay,\nSend the light! Send the light!\n\n3 Let us pray that grace may ev'rywhere\nabound, \"Send the light! Send the light!\"\nAnd a Christ-like spirit ev'rywhere be found,\nSend the light! Send the light!\n\n4 Let us not grow weary in the work of love,\n\"Send the light! Send the light!\"\nLet us gather jewels for a crown above,\nSend the light! Send the light!","sourcePage":34},{"id":"hymn-035","number":35,"title":"BLESSED ASSURANCE","subtitle":null,"lyrics":"1 Blessed assurance, Jesus is mine!\nOh, what a foretaste of glory divine!\nHeir of salvation, purchase of God,\nborn of his Spirit, washed in his blood.\n\nRefrain:\nThis is my story, this is my song,\npraising my Savior all the day long.\nThis is my story, this is my song,\npraising my Savior all the day long.\n\n2 Perfect communion, perfect delight,\nvisions of rapture now burst on my sight.\nAngels descending bring from above\nechoes of mercy, whispers of love. [Refrain]\n\n3 Perfect submission, all is at rest.\nI in my Savior am happy and bless’d,\nwatching and waiting, looking above,\nfilled with his goodness, lost in his love.\n[Refrain]","sourcePage":35},{"id":"hymn-036","number":36,"title":"I SURRENDER ALL","subtitle":null,"lyrics":"1 All to Jesus I surrender,\nAll to Him I freely give;\nI will ever love and trust Him,\nIn His presence daily live.\n\nRefrain:\nI surrender all, I surrender all;\nAll to Thee, my blessed Savior,\nI surrender all.\n\n2 All to Jesus I surrender,\nMake me, Savior, wholly Thine;\nLet me feel Thy Holy Spirit,\nTruly know that Thou art mine. [Refrain]\n\n3 All to Jesus I surrender,\nLord, I give myself to Thee;\nFill me with Thy love and power,\nLet Thy blessing fall on me. [Refrain]","sourcePage":36},{"id":"hymn-037","number":37,"title":"FACE TO FACE","subtitle":null,"lyrics":"1 Face to face with Christ, my Savior,\nFace to face- what will it be\nWhen with rapture I behold him,\nJesus Christ who died for me?\n\nRefrain:\nFace to face I shall behold him,\nFar beyond the starry sky;\nFace to face in all his glory,\nI shall see him by and by.\n\n2 Only faintly now I see him\nWith the darkened veil between,\nBut a blessed day is coming\nWhen his glory shall be seen. [Refrain]\n\n3 What rejoicing in his presence,\nWhen are banished grief and pain;\nWhen the crooked ways are straightened\nAnd the dark things shall be plain. [Refrain]\n\n4 Face to face- oh, blissful moment!\nFace to face- to see and know;\nFace to face with my Redeemer,\nJesus Christ who loves me so. [Refrain]","sourcePage":37},{"id":"hymn-038","number":38,"title":"JESUS SAVES","subtitle":null,"lyrics":"1 We have heard the joyful sound:\nJesus saves! Jesus saves!\nSpread the tidings all around:\nJesus saves! Jesus saves!\nBear the news to ev'ry land,\nClimb the steeps and cross the waves;\nOnward! 'tis our Lord's command;\nJesus saves! Jesus saves!\n\n2 Waft it on the rolling tide:\nJesus saves! Jesus saves!\nTell to sinners far and wide:\nJesus saves! Jesus saves!\nSing, ye islands of the sea;\nEcho back, ye ocean caves;\nEarth shall keep her jubilee:\nJesus saves! Jesus saves!\n\n3 Sing above the battle strife:\nJesus saves! Jesus saves!\nBy His death and endless life:\nJesus saves! Jesus saves!\nSing it softly through the gloom,\nWhen the heart for mercy craves;\nSing in triumph o'er the tomb:\nJesus saves! Jesus saves!\n\n4 Give the winds a mighty voice:\nJesus saves! Jesus saves!\nLet the nations now rejoice:\nJesus saves! Jesus saves!\nShout salvation full and free,\nHighest hills and deepest caves;\nThis our song of victory:\nJesus saves! Jesus saves!","sourcePage":38},{"id":"hymn-039","number":39,"title":"TIL SO SWEET TO TRUST IN JESUS","subtitle":null,"lyrics":"1 'Tis so sweet to trust in Jesus,\nand to take him at his word;\njust to rest upon his promise,\nand to know, \"Thus saith the Lord.\"\n\nRefrain:\nJesus, Jesus, how I trust him!\nHow I've proved him o'er and o'er!\nJesus, Jesus, precious Jesus!\nO for grace to trust him more!\n\n2 O how sweet to trust in Jesus,\njust to trust his cleansing blood;\nand in simple faith to plunge me\nneath the healing, cleansing flood! [Refrain]\n\n3 Yes, 'tis sweet to trust in Jesus,\njust from sin and self to cease;\njust from Jesus simply taking\nlife and rest, and joy and peace. [Refrain]","sourcePage":39},{"id":"hymn-040","number":40,"title":"FAIREST LORD JESUS","subtitle":null,"lyrics":"1 Fairest Lord Jesus,\nruler of all nature,\nO thou of God and man the Son,\nThee will I cherish,\nThee will I honor,\nthou, my soul's glory, joy, and crown.\n\n2 Fair are the meadows,\nfairer still the woodlands,\nrobed in the blooming garb of spring:\nJesus is fairer,\nJesus is purer\nwho makes the woeful heart to sing.\n\n3 Fair is the sunshine,\nfairer still the moonlight,\nand all the twinkling starry host:\nJesus shines brighter,\nJesus shines purer\nthan all the angels heaven can boast.\n\n4 Beautiful Savior!\nLord of all the nations!\nSon of God and Son of Man!\nGlory and honor,\npraise, adoration,\nnow and forevermore be thine.","sourcePage":40},{"id":"hymn-041","number":41,"title":"SUNSHINE IN MY SOUL","subtitle":null,"lyrics":"1 There is sunshine in my soul today,\nMore glorious and bright\nThan glows in any earthly sky,\nFor Jesus is my light.\n\nRefrain:\nO there’s sunshine, blessed sunshine,\nWhen the peaceful happy moments roll:\nWhen Jesus shows His smiling face,\nThere is sunshine in the soul.\n\n2 There is music in my soul today,\nA carol to my King,\nAnd Jesus, listening, can hear\nThe songs I cannot sing. [Refrain]\n\n3 There is springtime in my soul today,\nFor when the Lord is near,\nThe dove of peace sings in my heart,\nThe flowers of grace appear. [Refrain]\n\n4 There is gladness in my soul today,\nAnd hope and praise and love\nFor blessings which He gives me now,\nFor joys \"laid up\" above. [Refrain]","sourcePage":41},{"id":"hymn-042","number":42,"title":"RING THE BELLS OF HEAVEN","subtitle":null,"lyrics":"1 Ring the bells of heaven!\nThere is joy today,\nFor a soul, returning from the wild!\nSee, the Father meets him out upon the way,\nWelcoming His weary, wandering child.\n\nRefrain:\nGlory! Glory! How the angels sing:\nGlory! Glory! How the loud harps ring!\n'Tis the ransomed army, like a mighty sea,\nPealing forth the anthem of the free.\n\n2 Ring the bells of heaven!\nThere is joy today,\nFor the wanderer now is reconciled;\nYes, a soul is rescued from his sinful way,\nAnd is born anew, a ransomed child. [Refrain]\n\n3 Ring the bells of heaven!\nSpread the feast today!\nAngels, swell the glad triumphant strain!\nTell the joyful tidings, bear it far away!\nFor a precious soul is born again. [Refrain]","sourcePage":42},{"id":"hymn-043","number":43,"title":"WHOSOEVER MEANETH ME","subtitle":null,"lyrics":"1. I am happy today and the sun shines bright,\nThe clouds have been rolled away;\nFor the Savior said, whosoever will\nMay come with Him to stay.\n\"Whosoever,\" surely meaneth me,\nSurely meaneth me, O surely meaneth me;\n\"Whosoever,\" surely meaneth me,\n\"Whosoever,\" meaneth me.\n\n2. All my hopes have been raised, O His name be\npraised,\nHis glory has filled my soul;\nI've been lifted up, and from sin set free,\nHis blood has made me whole.\n\"Whosoever,\" surely meaneth me,\nSurely meaneth me, O surely meaneth me;\n\"Whosoever,\" surely meaneth me,\n\"Whosoever,\" meaneth me.\n\n3. O what wonderful love, O what grace divine,\nThat Jesus should die for me;\nI was lost in sin, for the world I pined,\nBut now I am set free.\n\"Whosoever,\" surely meaneth me,\nSurely meaneth me, O surely meaneth me;\n\"Whosoever,\" surely meaneth me,\n\"Whosoever,\" meaneth me.","sourcePage":43},{"id":"hymn-044","number":44,"title":"JUST AS I AM","subtitle":null,"lyrics":"1 Just as I am, without one plea,\nbut that thy blood was shed for me,\nand that thou bidd'st me come to thee,\nO Lamb of God, I come, I come.\n\n2 Just as I am, and waiting not\nto rid my soul of one dark blot,\nto thee, whose blood can cleanse each\nspot,\nO Lamb of God, I come, I come.\n\n3 Just as I am, though tossed about\nwith many a conflict, many a doubt,\nfightings and fears within, without,\nO Lamb of God, I come, I come.\n\n4 Just as I am, thou wilt receive,\nwilt welcome, pardon, cleanse, relieve;\nbecause thy promise I believe,\nO Lamb of God, I come, I come.","sourcePage":44},{"id":"hymn-045","number":45,"title":"BRING THEM IN","subtitle":null,"lyrics":"1 Hark! 'Tis the Shepherd's voice I hear,\nOut in the desert dark and drear,\nCalling the sheep who've gone astray,\nFar from the Shepherd's fold away.\n\nRefrain:\nBring them in, bring them in,\nBring them in from the fields of sin;\nBring them in, bring them in,\nBring the wandering ones to Jesus.\n\n2 Who'll go and help this Shepherd kind,\nHelp Him the wandering ones to find?\nWho'll bring the lost ones to the fold,\nWhere they'll be sheltered from the cold?\n[Refrain]\n\n3 Out in the desert hear their cry,\nOut on the mountains wild and high;\nHark! 'Tis the Master speaks to thee,\n\"Go find My sheep where'er they be.\" [Refrain]","sourcePage":45},{"id":"hymn-046","number":46,"title":"HOLY HOLY HOLY","subtitle":null,"lyrics":"1. Holy, holy, holy! Lord God Almighty!\nEarly in the morning our song shall rise to\nthee.\nHoly, holy, holy! merciful and mighty!\nGod in three Persons, blessed Trinity!\n\n2. Holy, holy, holy! all the saints adore thee,\nCasting down their golden crowns around\nthe glassy sea.\nCherubim and seraphim, falling down\nbefore thee,\nWho was and is and evermore shall be.\n\n3. Holy, Holy, Holy! though the darkness hide\nthee,\nThough the eye of sinful man thy glory may\nnot see,\nOnly thou art holy; there is none beside\nthee,\nPerfect in pow'r, in love, and purity.\n\n4. Holy, holy, holy! Lord God Almighty!\nAll thy works shall praise thy name, in earth,\nand sky, and sea;\nHoly, holy, holy! merciful and mighty!\nGod in three Persons, blessed Trinity.","sourcePage":46},{"id":"hymn-047","number":47,"title":"DOXOLOGY","subtitle":null,"lyrics":"Praise God, from whom all blessings flow;\nPraise Him, all creatures here below;\nPraise Him above, ye heav’nly host;\nPraise Father, Son, and Holy Ghost.\nAmen","sourcePage":47},{"id":"hymn-048","number":48,"title":"HE LIVES","subtitle":null,"lyrics":"I serve a risen Saviour, He's in the world today\nI know that He is living, whatever men may say\nI see His hand of mercy, I hear His voice of cheer\nAnd just the time I need Him He's always near\n\nKORO:\nHe lives (He lives), He lives (He lives),\nChrist Jesus lives today\nHe walks with me and talks with me\nAlong life's narrow way\nHe lives (He lives), He lives (He lives),\nSalvation to impart\nYou ask me how I know He lives?\nHe lives within my heart\n\nIn all the world around me I see His loving care\nAnd though my heart grows weary I never will\ndespair\nI know that He is leading, through all the stormy\nblast\nThe day of His appearing will come at last\n\nRejoice, rejoice, O Christian Lift up your voice and\nsing\nEternal hallelujahs to Jesus Christ, the King\nThe Hope of all who seek Him, the Help of all who\nfind\nNone other is so loving, so good and kind","sourcePage":48},{"id":"hymn-049","number":49,"title":"THERE SHALL BE SHOWERS OF BLESSING","subtitle":null,"lyrics":"There shall be showers of blessing:\nThis is the promise of love;\nThere shall be seasons refreshing,\nSent from the Savior above.\n\nShowers of blessing,\nShowers of blessing we need;\nMercy-drops round us are falling,\nBut for the showers we plead.\n\nThere shall be showers of blessing—\nPrecious reviving again;\nOver the hills and the valleys,\nSound of abundance of rain.\n\nThere shall be showers of blessing;\nSend them upon us, O Lord!\nGrant to us now a refreshing;\nCome, and now honor Thy Word.\n\nThere shall be showers of blessing;\nO that today they might fall,\nNow as to God we’re confessing,\nNow as on Jesus we call!\n\nThere shall be showers of blessing,\nIf we but trust and obey;\nThere shall be seasons refreshing,\nIf we let God have His way.","sourcePage":49},{"id":"hymn-050","number":50,"title":"COUNT YOUR BLESSINGS","subtitle":null,"lyrics":"1 When upon life's billows you are tempest tossed,\nWhen you are discouraged, thinking all is lost,\nCount your many blessings, name them one by one,\nAnd it will surprise you what the Lord hath done.\n\nRefrain:\nCount your blessings, name them one by one;\nCount your blessings, see what God hath done;\nCount your blessings, name them one by one;\nCount your many blessings, see what God hath done.\n\n2 Are you ever burdened with a load of care?\nDoes the cross seem heavy you are called to bear?\nCount your many blessings, ev'ry doubt will fly,\nAnd you will be singing as the days go by. [Refrain]\n\n3 When you look at others with their lands and gold,\nThink that Christ has promised you His wealth untold;\nCount your many blessings, money cannot buy\nYour reward in heaven, nor your home on high.\n[Refrain]\n\n4 So, amid the conflict, whether great or small,\nDo not be discouraged, God is over all;\nCount your many blessings, angels will attend,\nHelp and comfort give you to your journey's end.\n[Refrain]","sourcePage":50},{"id":"hymn-051","number":51,"title":"GO, TELL IT ON THE MOUNTAIN","subtitle":null,"lyrics":"While shepherds kept their watching\nO'er silent flocks by night\nBehold throughout the heavens\nThere shone a Holy light\n\nKORO\nGo, tell it on the mountain\nOver the hills and everywhere\nGo, tell it on the mountain\nThat Jesus Christ is born\n\nThe shepherds feared and trembled\nWhen, lo! Above the Earth\nRang out the angel chorus\nThat hailed our Savior's birth\n\nDown in a lowly manger\nOur humble Christ was born\nAnd brought us all salvation\nThat blessed Christmas morn","sourcePage":51},{"id":"hymn-052","number":52,"title":"HOW GREAT THOU ART","subtitle":null,"lyrics":"O Lord my God When I in awesome wonder\nConsider all the works Thy hands have made,\nI see the stars, I hear the rolling thunder,\nThy pow’r throughout The universe displayed!\n\nChorus\nThen sings my soul, My Savior God, to Thee;\nHow great Thou art, How great Thou art!\nThen sings my soul, My Savior God, to Thee;\nHow great Thou art, How great Thou art!\n\nWhen thru the woods And forest glades I wander\nAnd hear the birds Sing sweetly in the trees,\nWhen I look down From lofty mountain grandeur\nAnd hear the brook And feel the gentle breeze,\n\nAnd when I think That God, His Son not sparing,\nSent Him to die, I scarce can take it in –\nThat on the cross, My burden gladly bearing,\nHe bled and died To take away my sin!\n\nWhen Christ shall come With shout of acclamation\nAnd take me home, What joy shall fill my heart!\nThen I shall bow In humble adoration\nAnd there proclaim, My God, how great Thou art!","sourcePage":52},{"id":"hymn-053","number":53,"title":"AMAZING GRACE","subtitle":null,"lyrics":"Amazing grace, how sweet the sound\nThat saved a wretch like me\nI once was lost, but now I'm found\nWas blind, but now I see\n\n'Twas grace that taught my heart to fear\nAnd grace my fears relieved\nHow precious did that grace appear\nThe hour I first believed\n\nThrough many dangers, toils, and snares\nWe have already come\n'Twas grace that brought us safe thus far\nAnd grace will lead us home\n\nWhen we've been there ten thousand\nyears\nBright shining as the sun\nWe've no less days to sing God's praise\nThan when we've first begun\nThan when we've first begun","sourcePage":53},{"id":"hymn-054","number":54,"title":"I KNOW WHO HOLDS TOMMOROW","subtitle":null,"lyrics":"1 I don't know about tomorrow,\nI just live from day to day.\nI don't borrow from its sunshine,\nFor its skies may turn to gray.\nI don't worry o'er the future,\nFor I know what Jesus said,\nAnd today I'll walk beside Him,\nFor He knows what is ahead.\n\nRefrain:\nMany things about tomorrow,\nI don't seem to understand;\nBut I know who holds tomorrow,\nAnd I know who holds my hand.\n\n2 Every step is getting brighter,\nAs the golden stairs I climb;\nEvery burden's getting lighter;\nEvery cloud is silver lined.\nThere the sun is always shining,\nThere no tear will dim the eye,\nAt the ending of the rainbow,\nWhere the mountains touch the sky. [Refrain]\n\n3 I don't know about tomorrow,\nIt may bring me poverty;\nBut the one who feeds the sparrow,\nIs the one who stands by me.\nAnd the path that be my portion,\nMay be through the flame or flood,\nBut His presence goes before me,\nAnd I'm covered with His blood. [Refrain]","sourcePage":54},{"id":"hymn-055","number":55,"title":"MAKE ME A BLESSING","subtitle":null,"lyrics":"Out in the highways and byways of life\nMany are weary and sad\nCarry the sunshine where darkness is rife\nMaking the sorrowing glad\n\nChorus\nMake me a blessing make me a blessing\nOut of my life may Jesus shine\nMake me a blessing O Savior I pray\nMake me a blessing to someone today\n\nTell the sweet story of Christ and His love\nTell of His pow'r to forgive\nOthers will trust Him if only you prove\nTrue ev’ry moment you live\n\nGive as 'twas given to you in your need\nLove as the Master loved you\nBe to the helpless a helper indeed\nUnto your mission be true","sourcePage":55},{"id":"hymn-056","number":56,"title":"THE OLD ACCOUNT WAS SETTLED","subtitle":null,"lyrics":"There was a time on earth when in the book of Heav’n\nAn old account was standing for sins yet unforgiv’n;\nMy name was at the top, and many things below—\nI went unto the Keeper, and settled long ago.\n\nRefrain:\nLong ago, long ago,\nYes, the old account was settled long ago;\nAnd the record’s clear today, for He washed my sins\naway,\nWhen the old account was settled long ago.\n\nThe old account was large, and growing every day,\nFor I was always sinning, and never tried to pay;\nBut when I looked ahead, and saw such pain and woe,\nI said that I would settle—I settled long ago.\n\nWhen in that happy home, my Savior’s home above,\nI’ll sing redemption’s story, and praise Him for His love;\nI’ll not forget that book, with pages white as snow,\nBecause I came and settled, and settled long ago.\n\nO sinner, trust the Lord, be cleansed of all your sin,\nFor thus He hath provided for you to enter in;\nAnd then if you should live a hundred years below,\nUp there you’ll not regret it—you settled long ago.","sourcePage":56},{"id":"hymn-057","number":57,"title":"SI JESUS AY KAIBIGAN","subtitle":"(What a Friend We have In Jesus)","lyrics":"Si Jesus ay kaibigan sala’t hapis pinasan\nAnopng laking karapatang Dios\nmapanalanginan\nGaanong kapayapaan ang malimi’t\ntalikdan\nDahil sa kinaligtaang Dios ay panalanginan\n\nMay pagsubok ba’t tukso man ligalig kahit\nsaan\nH’wag tayong manlulupaypay dumalangin\nnga lamang\nMay tapat bang kaibigang kahati mo sa\nlumbay\nAlam ating kahinaan Jesus ang dalanginan\n\nMahina’t nabibigatan sa sapin saping\npasan\nSi Jesus ating kanlungan Siya ang\ndalanginan\nHinamak ba't iniwanan ng mga kaibigan\nBisig N’ya’y ating tanggulan Siya ang\nkaaliwan","sourcePage":57},{"id":"hymn-058","number":58,"title":"O! BUKAL NG PAGPAPALA","subtitle":"(Come, Thou Fount)","lyrics":"O! Bukal ng pagpapala awit ko ay itugma\nDaloy ng maraming awa awit kang masagana\nTuruan akong umawit ng awit d’yan sa langit\nSa bundok ako’y itindig, bundok ng ‘Yong pag-\nibig\n\nTulong Mo’y dito na kamtan Pala Mo’y ibinigay\nAasahan ko ay Ikaw  hanggang kabilang buhay\nSi Jesus ang S’yang humanap sa aking na\ntiwalag\nAt nang upang mailigtas Dugo N’ya’y ibinayad\n\nAng habag Mo’y araw-araw buhay ko’y aking\nutang\nKabutihan Mo’y ialay ako sa ‘yo’y ipisan\nAko ay naging lagalag at nawaglit sa landas\nPuso ko ngayon ay tanggap lagyan ng iyong\ntatak","sourcePage":58},{"id":"hymn-059","number":59,"title":"SA BAWAT SAGLIT AT BAWAT ARAW","subtitle":"(Day By Day)","lyrics":"Sa bawat saglit at bawat araw sa hirap may\nangkop na lakas\nKung Ama’y pinagtitiwalaan ako’y walang\nkatatakutan\nS’yang puso’y Puspos ng kaawaan t’wing araw\nlaa’y mabuti lang\nKabahaging hapdi’t kasiyahan pagpapagal at\npahingalay\n\nPanginoo’y malapit t’wing araw pinakakamit\nkaawaan\nSa pasanin ko’y may kaaliwan tagapayo’t\nkapangyarihan\nAng pag-iingat sa Kanyanga nak sa Kanyang\nsarili’y inatas\n“Lakas mo’y kung ano ang ‘yong araw” pangakong\nKanyang iginawad\n\nTulungan Mong sa kapighatian sa Iyong pangako’y\nmanangan\nNang h’wag kong mawaglit kaaliwan na sa Salita\nMo’y ‘Yong laan\nTulungan Mo upang kapagalan ibilang buhay\nsa’Yong kamay\nSa bawat saglit at bawat araw hanggang datnin ko\nang ‘Yong bayan","sourcePage":59},{"id":"hymn-060","number":60,"title":"SA DIOS ANG LWALHATI","subtitle":"(To God Be The Glory)","lyrics":"Sa Dios ang lwalhati gawa’y dakila\nMundo’y minahal anak N’ya’y binigay\nBuhay alay N’yang pantubos sa sala\nSa lahat na buksan pinto ng buhay\n\nKORO\nPuri sa Panginoon tinig N’ya’y pakinggan\nPuri sa Panginoon tayo’y mangagalak!\nLapit sa Ama sa anak dumaan\nGawa N’ya’y dakila lwalhati’y bigyan\n\nBili sa dugo sakdal na katubsan\nPangako ng Dios sa bawat naligtas\nSasampalatayang makasalanan\nAy tatanggap kay Jesus ng patawad\n\nGawa’t turo N’ya sa ati’y dakila\nGalak natin kay Jesus ay dakila\nNgunit Dalisay sa laki’y higit pa\nAting pagkamangha kung S’ya’y makita","sourcePage":60},{"id":"hymn-061","number":61,"title":"KUBLIHAN KAPAG MAY BAGYO","subtitle":"(A Shelter in the Time of Storm)","lyrics":"Si Jesus ang ating bato kublihan kapag may\nbagyo\nLakas sa hirap at tukso kublihan kapag may\nbagyo\n\nKORO\nSi Jesus ang bato ng manlalakbay, manlalakbay,\nmanlalakbay\nSi Jesus ang bato ng manlalakbay\nKublihan kapag may bagyo\n\nMaging sa araw at gabi kublihan kapag may\nbagyo\nWalang sindak sa kaaaway kublihan kapag may\nbagyo\n\nSa ulan init at lamig kublihan kapag may bagyo\nLagi ang Kanyang pag-ibig kublihan kapag may\nbagyo\n\nBatong banal Diyos naming kublihan kapag may\nbagyo\nKaming aba’y kalingain kublihan kapag may\nbagyo","sourcePage":61},{"id":"hymn-062","number":62,"title":"ANG PANGINOO’Y SIYANG HUHUKOM","subtitle":"(When the Roll is Called up Yonder)","lyrics":"Kung ang tambuli ng Panginoon ay tumunog na\nAt ang maligayang araw bumuka\nKung ang lahat ng tao’y nagkatipon na roon\nTatawagin ako ni Jesus doon\n\nKORO\nKung lahat ay magkatipon, kung lahat ay\nmagkatipon, kung lahat ay nagkatipon\nTatawagin ako ni Jesus doon\n\nAng mga patay ay magbabangon sa araw na\n‘yon\nMagsisiligaya sa Panginoon\nKung ang lahat ng pinili sa langit ay magkatipon\nTatawagin ako ni Jesus doon\n\nBayaan akong mag-ingat hanggang Siya’y\ndumatal\nItatanghal ko Kanyang kabutihan\nUpang ako ay masama sa Kaniya kailanman\nAt hwag sa walang hanggang kamatayan","sourcePage":62},{"id":"hymn-063","number":63,"title":"TUNAY KANG MATAPAT","subtitle":"(Great is Thy Faithfulness)","lyrics":"Tunay kang matapat Dios naming Ama\nDi nagbabago, di nag-iiba\nMaghapon, magtanghali, maumaga\nSa buong panahon, matapat Ka!\n\nKORO\nTunay Kang matapat, Tunay kang matapat\nAraw-araw aking namamalas\nAng Iyong kabutihang walang kupas\nTunay Kang matapat sa paglingap\n\nTag-araw’t tag-ulan at ang tag-ani\nAraw, buwa’t bituin sa gabi\nNag-aawitang langit sumasaksi\nSa katapatan Mong anong laki\n\nKapatawaran at kapayapaan\nMga pangako Mong umaakbay\nLakas ngayo’t pag-asang sumisilang\nAng lahat ng ito’y Iyong bigay","sourcePage":63},{"id":"hymn-064","number":64,"title":"MAY LUPANG SAKDAL NG GANDA","subtitle":"(Sweet By and By)","lyrics":"May lupang pagkaganda ganda na handa\nsa atin ng Ama\nAt sa daa’y hintay Tayo N’ya sa tahana’y\nipagsasama\n\nKORO\nPanahong masaya kung tayo ay\nsalubungin N’ya\nPanahong masaya sa langit tayo’y\nmagkikita\n\nSa baybaying sakdal ganda awit nati’y di\nmagmamaliw\nAng hilahil doo’y wala na kapayapaa’y\nsasa atin\n\nSa Amang nasa kalangitan puri ay ating\niaalay\nDahil sa Kanyang pagmamahal at sa pala\nN’yang binigay","sourcePage":64},{"id":"hymn-065","number":65,"title":"MAKIKITA KONG MUKHAAN","subtitle":"(Face To Face)","lyrics":"Mukhaan kong makikita si Cristo’y anong ganda\nMasaya ko s’yang mamasdan Na sa aki’y\nnamatay\n\nKORO\nMukhaan kong makikita, makikita kong tunay\nAng Kanyang kalwalhatian, Do’n sa kabilang\nbuhay\n\nSa ngayon ay malabo pa natin S’yang nakikita\nBalang araw tutunghayan, mukha n’yang sakdal\nkinang\n\nAnong laking aliwalas! Pagkapawi ng hirap\nPagka twid ng likong landas pagkapawi ng ulap\n\nO! anong palad na araw, kung S’ya’y aking\nmamasdan\nSa kay Cristong kagandahan na sa ki’y\nnagmamahal","sourcePage":65},{"id":"hymn-066","number":66,"title":"DALHIN ANG ILAW","subtitle":"(Send the Light)","lyrics":"Tawag sa mga aloy na pakinggan\n“Na dalhin ang ilaw”\nMay mga kaluluwang na didimlan\nAt na nga liligaw\n\nKORO\nAng ilaw ng bagong balita ang s’yang\npaliwanagin\nAng lahat ng naging aba\nSa salang sapin sapin\n\nBiyaya ni Jesus ay sumagana\n“Na taglay ang ilaw”\nAt ang kanyang aral ay ibalita\nSa mga na ligaw\n\nSa gawang pag-ibig  hwag manglupaypay\n“At dalhin ang Ilaw”\nAt samantalang may buhay na taglay\nItanglaw ang Ilaw","sourcePage":66},{"id":"hymn-067","number":67,"title":"MASAYANG BALITA’Y ATING NARINIG","subtitle":"(Jesus Saves)","lyrics":"Balita’y ating talos naligtas kay Jesus\nKagalaka’y isabog naligtas kay Jesus\nSa bayan ito’y dalhin, bundok, dagat\nlakbayin\nSulong sundin ang utos, at ligtas kay\nJesus\n\nAwitin nating lahat, Kay Jesus ay ligtas\nBuong lupa’y magalak, Kay Jesus ay ligtas\nSiya nga ang namatay, at naghandog ng\nbuhay\nUpang kamtan pangakong kay Jesus ay\nligtas\n\nTinig nati’y itaas, kay Jesus ay ligtas\nBalita ay ikalat, kay Jesus ay ligtas\nUmawit ng tagumpay, Dahil sa kaligtasan\nMabuhay at mamatay, Kay Jesus ay ligtas","sourcePage":67},{"id":"hymn-068","number":68,"title":"ANG DAKILANG BIYAYA NI JESUS","subtitle":"(Wonderful Grace of Jesus)","lyrics":"Ang dakilang biyaya ni Jesus sa akin\nUmid ang aking dila’t di kayang sambitin\nPasanin ko’y inibis diwa ko’y lumaya\nDahil sa inabot ng Kanyang biyaya!\n\nKORO\nAng dakilang biyaya ni Jesus\nAy malalim pa kaysa dagat\nMataas sa bundok, bukal ng indayog\nAt maging sa akin ay sapat (oo sapat)\nHigit ang lapad sa aking sala\nLampas sa aking kasalanan\nO! purihin natin ang kay Jesus na Pangalan\n\nAng dakilang biyaya ni Jesus sa lahat\nDahil diya’y luminis at ako’y naligtas\nTanikala’y naputol, pinalaya ako\nPagka’t inabot ng biyaya ni Cristo\n\nAnd dakilang biyaya kahit na pusakal\nNa salari’y nagiging tunay nan gang banal\nKapayapaa’t langit ay idinudulot\nSa sinumang nagtitiwala kay Jesus","sourcePage":68},{"id":"hymn-069","number":69,"title":"MAKAPANGYARIHAN ANG DUGO","subtitle":"(There’s Power in the Blood)","lyrics":"Nais mo bang maibsan ang pasan?\nMakapangyarihan ang dugo\nSa sala ay makalayang tunay\nMay tanging lunas sa dugo\n\nKORO\nDugong mahal ng Kordero ay makapangyarihan\nDugo lamang ni Cristong banal panghugas sa\nkasalanan\n\nNais mo ang lubos na tagumpay?\nMakapangyarihan ang dugo\nSa masasamang pita ng laman\nMay tanging lunas sa dugo\n\nNais mong kalulwa ay kuminang?\nMakapangyarihan ang dugo\nLumapit ka sa bukal ng buhay\nMay tanging lunas sa dugo\n\nNais mo bang maglingkod kay Jesus?\nMakapangyarihan ang dugo\nNais mong sa twitwina ay Puspos\nMay tanging lunas sa dugo","sourcePage":69},{"id":"hymn-070","number":70,"title":"MATAMIS ANG MAGTIWALA KAY","subtitle":null,"lyrics":"JESUS\n(‘Tiss So Sweet To Trust in Jesus)\n\nAnong tamis magtiwala Kay Jesus na\nSalita\nSa pangako’y magpahinga at sa Dios\nmanainga\n\nKORO\nJesus pinagtiwalaan at aking sinubukan\nJesus aking kalulwa sa awa mo’y aasa\n\nJesus tanggapin ka lamang sala ko’y\nnahugasan\nNg dugo mong mahalaga na pantubos sa\nsala\n\nDahil kay Jesus iiwan ang sarili at sala\nAt sa Kanya ay kukuha, buhay, galak, pag-\nasa\n\nTunay akong natitiwa natutong magtiwala\nSa aking Tagapagligtas ngayon at\nhanggang wakas","sourcePage":70},{"id":"hymn-071","number":71,"title":"MAGTIWALA AT SUMUNOD","subtitle":"(Trust and Obey)","lyrics":"Kung tayo’y lumakad na kasama ng Diyos\nKay luwalhati at mapalad\nGumanap ng utos ni Jesus na Diyos\nAt magtiwala at sumunod\n\nKORO\nMagtiwala, at tayo’y sumunod\nNang maging maligaya sa piling ni Jesus\n\nWalang anino man, ni ulap saanman\nNgunit ngiti Nya’y namamasdan\nWala akong takot ni luha at lungkot\nPagka’t may tiwala’t pagsunod\n\nHindi matatalos tamis Nyang pag-ibig\nHangga’t di isuko mong lahat\nAng Kanyang biyaya, at atin Ligaya\nKakamtan kung tayo’y susunod\n\nSumama’y kaytamis kay Jesus malapit\nTayo’y lagi Nya’ng makaniig\nSundin Kanyang utos sumunod ng lubos\nMagtiwala at h’wag matakot","sourcePage":71},{"id":"hymn-072","number":72,"title":"CRISTIANO LAMANG","subtitle":"(Bringing in the Sheaves)","lyrics":"Matamis ang ngalan na lagda sa tanan\nAyon sa pahayag ng bagong tipan\nAy isang pangalang dakila at banal\nNanggaling kay Cristo, Cristiano lamang\n\nKORO:\nCristiano lamang, Cristiano lamang\nBanal kong pangalan Cristiano lamang\nCristiano lamang, Cristiano lamang\nTatahan sa langit magpakailanman\n\nBanal na pangalan tayo’y pinagsama\nSa pagluwalhati sa Diyos Ama\nSa ibang pangala’y walang kaligtasan\nLiban ang kay Jesus, Cristiano lamang\n\nAng langit na bayan ay siyang tahanan\nNg mga Cristiano sa huling araw\nDoo’y walang luha kundi tuwang panay\nKasama ni Cristo’y Cristianong tunay","sourcePage":72},{"id":"hymn-073","number":73,"title":"MASAGANG PALA","subtitle":"(There Shall Be Showers of Blessing)","lyrics":"Ibubuhos ang biyaya Pangako ng pagliyag\nPanahon ng kasiglahan ng masaganang\nulan\n\nKORO\nSaganang pala ang kailangan namin\nAwang natak sa paligid Sami’y pasaganain\n\nIbubuhos ang biyaya mahalaga’t\npambuhay\nDinggin sa gulod ang ugong ng\nmasaganang ulan\n\nIbubuhos ang biyaya sa amin ang ibigay\nPanginoo’y kasiglaha’t salita’y parangalan\n\nIbubuhos ang biyaya ipadalanang agad\nNgayong sa Dios naghahayag Kay Jesus\ntumatawag","sourcePage":73},{"id":"hymn-074","number":74,"title":"DOON SA KRUS NAMATAY SI JESUS","subtitle":"(Glory To His Name)","lyrics":"Doon sa krus namatay Siya\nDoon tinangisan ang sala\nDo’n dugo sa puso’y naadya\nGloria sa Kanya\n\nKORO\nGloria sa Kanya, Gloria sa Kanya\nDu’n dugo sa puso’y naadya\nGloria sa Kanya\n\nAko ay naligtas na Puspos\nSi Jesus ay nasa’king lubos\nAko’y kinupkop doon sa Krus\nGloria sa Kanya\n\nO! Bukal na nakalilinis\nAko ay galak sa paglapit\nDoon naligtas akong pilit\nGloria sa Kanya\n\nMagsilapit kayo sa bukal\nUpang kayo ay maging banal\nAt nang kayo ay maging sakdal\nGloria sa Kanya","sourcePage":74},{"id":"hymn-075","number":75,"title":"INIAALAY KO ANG LAHAT","subtitle":"(I Surrender All)","lyrics":"Kay Jesus ko iaalay\nLahat ay ibibigay\nSiyang aking aasahan\nAt sa Kanya tatahan\n\nKORO\nIniaalay ko, Iniaalay ko\nAng lahat sa iyo Cristo\nIniaalay ko\n\nKay Jesus ko iaalay\nPaluhod sa paanan\nKamunduhan ay iiwan\nKupkupin akong tunay\n\nKay Jesus ko iaalay\nGawin mo akong iyo\nDiwa mo ako’y puspusin\nMakitang ikaw’y akin","sourcePage":75},{"id":"hymn-076","number":76,"title":"MAPALAD NA KASIGURUHAN","subtitle":"(Blessed Assurance)","lyrics":"O! si Jesus ay aking tunay\nKalulwalhatian ay nalalasap\nTagapagmana at tinubos\nSa dugo’y nilinis na lubos\n\nKORO\nIto ang awit ko’t pahayag\nAng naligtas ay papurihan\nIto ang awit ko’t pahayag\nAraw gabi siiy’y pupurihin\n\nAko’y lubusang pasasakop\nSa pangitain ay nakikitang\nMga anghel ang nagdadala\nNg alingawngaw ng pagsinta\n\nWagas na nagpapahingala’y\nKay Cristo ay mayron kasiyahan\nHihintayin lamang sa Kanya\nAng masaganang pagmamahal","sourcePage":76},{"id":"hymn-077","number":77,"title":"MAY INIT SA AKING KALULUWA","subtitle":"(Sunshine in My Soul)","lyrics":"May init sa aking kaluluwa\nNa wala ngang katulad\nTanging kay Jesus nagmumula\nPagka’t syang Liwanag\n\nKORO\nMay Liwanag, O may Liwanag\nBuhay ko’y payapa, kaytamis\nKung si Jesus ang sya kong kapiling\nKaluluwa ko’y maningning\n\nMay awit sa aking kaluluwa\nNa alay ko kay Jesus\nSa pagpupuri at pagsamba\nNg ako’y matubos\n\nMay aliw sa aking kaluluwa\nNg dahil sa pag-asa\nSa pala nakaloob niya\nAko ay masaya","sourcePage":77},{"id":"hymn-078","number":78,"title":"MATAMIS NA AWIT NG KALANGITAN","subtitle":"(Ring the Bells of Heaven)","lyrics":"Matamis na awit ay sambitlain\nAt sa Panginoo’y ihain\nBuhat sa langit syang taglay sa’tin\nPayapa’t t’wang walang kahambing\n\nKORO\nLwalhati sa Diyos sa kaitaasan\nPuri ang inawit ng tanan\nAng awit na sa langit pakinggan\nNgayo’y muling ipagawitan\n\nAng sangkatauhan na may siphayo\nNgayo’y magalak yamang tanto\nPag-ibig ng Diyos kaya nga’t sinugo\nAng Anak niyang ating pintuho\n\nIlulan sa puso ang pagkilala\nSa nagdulot tubos sa sala\nAt kay Jesus na buhay ang anyaya\nIbigay ang ating pagsamba","sourcePage":78},{"id":"hymn-079","number":79,"title":"HIGIT SIYANG TUMATAMIS","subtitle":"(Still Sweeter Everyday)","lyrics":"Kay Jesus araw-araw puso ko’y nalalapit\nSa ringal ng umaga’y higit ang Kanyang dikit\nHigit S’yang marilag sa lahat kong iniisip\nAraw-araw sa aki’y higit S’yang tumatamis\n\nKORO\nDi natin malilirip dito sa pampangin\nDoo’y higit at higit ang tamis N’ya sa atin\n\nLwalhati N’ya’y bumati ng akin S’yang makita\nHigit S’yang maningning kaysa tala sa umaga\nKasiyahan ng kalul’wa ko sa Kanya’y labis\nAraw-araw sa aki’y higit S’yang tumatamis\n\nAng aking puso ma’y agad Niyang iniibsan\nSa Kaniyang piling pawi na ang kalungkutan\nKasiyahan ng kalul‘wa ko sa Kanya’y labis\nAraw-araw sa aki’y higit S’yang tumatamis","sourcePage":79},{"id":"hymn-080","number":80,"title":"KUNG LAHAT AY SUMAPIT","subtitle":"(When We All Get To Heaven)","lyrics":"Awitin ang pag-ibig ni Jesus\nAwitin ang awa N’yang puspos\nSa tahanang walang lungkot\nNa inihandang lubos\n\nKORO\nKung lahat ay sumapit anong galak ating\ntatamuhin\nKay Jesus sa langit tagumpay at t’wa’y awitin\n\nTayo ay magpatuloy na tapat\nUmasa’t maglingkod na ganap\nNang upang ating mamasdan\nKanyang kal’walhatian\n\nSulong hanggang sa ating matamo\nAng palang handa sa Kristyano\nUpang makasama tayo\nDo’n sa langit ni Cristo","sourcePage":80},{"id":"hymn-081","number":81,"title":"NANG TANGGAPIN KO SI JESUS","subtitle":"(Since Jesus Came Into My Heart)","lyrics":"Gaano ang pagkabago ng buhay\nNang si Cristo ay tanggapin\nBinigyan N’ya ng ilaw ang kalul’wa ko\nNang si Cristo ay tanggapin\n\nKORO\nNang si Cristo ay tanggapin\nNang si Cristo ay tanggapin\nMay baha ng kat’waan ang kalul’wa ko\nNang si Cristo ay tanggapin\n\nHindi nan ga ako naligaw ng daan\nMula nang Siya’y tanggapin\nAng manga kasalanan ko’y nahugasan\nNang si Cristo ay tanggapin\n\nMay pag-asa akong hindi magagalaw\nMula nang Siya’y tanggapin\nAt walang ulap ng pangamba sa daan\nMula nang Siya’y tanggapin\n\nSa dilim ng kamatayan ay may tanglaw\nMula nang Siya’y tanggapin\nAng pintuan ng bayan ay natatanaw\nMula nang Siya’y tanggapin","sourcePage":81},{"id":"hymn-082","number":82,"title":"DI KO ALAM ANG BIYAYA","subtitle":"(I Know Whom I Have Believed)","lyrics":"Di ko alam ang dahilan biyaya’y nakamtan\nAkong masama’y minahal tinubos na tunay\n\nKORO\nNgunit aking naaalaman na Kanyang laging\nmaiingatan\nAking kalul’wa at buhay hanggang Siya’y\ndumadal\n\nHindi ko natatalastas pa’nong iniligtas\nNi pan’nong Salita Niya’y taglay ay patawad\n\nDi ko batid ang pagkilos Espiritu ng Dios\nInihahayag si Jesus na S’yang Manunubos\n\nDi ko alam kung kailan babalik si Jesus\nKung dadaan sa libingan O sa ulap lamang","sourcePage":82},{"id":"hymn-083","number":83,"title":"SINUMA’Y LUMAPIT SA AKIN","subtitle":"(“Whosoever” Meaneth Me)","lyrics":"Ako ay lubhang maligaya ngayon\nSa mapiling anyaya\nSinuman sabi ng Panginoon\nLumapit sa Kanya\n\nKORO\nO! Anong galak ang tumugon\nSa anyaya ng ating Panginoon\nLumapit ka’t kusang paampon\nO! Lumapit ka ngayon\n\nLahat ng pag-asa ko’y na kay Jesus\nO! purihin S’yang lubos\nKalul’wa ko ay Kanyang tinubos\nNg dugong nabuhos\n\nAng pag-ibig ni Cristo ay dakila\nSa lahat ng nilikha\nBuhay N’ya’y kusang napariwara\nNang ako’y lumaya","sourcePage":83},{"id":"hymn-084","number":84,"title":"SA NGALAN NI JESUS","subtitle":"(The Banner of The Cross)","lyrics":"May isang Pangalang tanging kaloob\nSa silong nitong langit\nSiya’y walang iba kundi si Jesus\nNagbata ng pasakit\n\nKORO\nSa ngalan ni Jesus\nBawat tuhod ay iluhod\nSa kalangitang sinukod\nNgalan Niya’y itampok\n\nMaliban kay Jesus wala nang iba\nDapat na panaligan\nAng lahat ay ating hingin sa Kanya\nAt Kanyang ibibigay\n\nDahil sa sala ng sangkatauhan\nSi Jesus ay nananog\nKusang inihandog ang Kanyang buhay\nTayo nga ay tinubos","sourcePage":84},{"id":"hymn-085","number":85,"title":"O! CRISTIANONG KAWAL","subtitle":"(Onward, Christian Soldiers)","lyrics":"O! Cristianong kawal hayo sa laban\nAng Krus ni Jesus ang nasa unahan\nSi Cristong marangal pumapatnubay\nHayo sa digmaan Siya ang sundan\n\nKORO\nO! Cirstianong kawal hayo sa laban\nSi Jesus ang unang nakikilaban\n\nAng Iglesiang hirang hukbong kalakhan\nAng dinadaana’y landas na banal\nKatawang iisa nagtutulungan\nIisa ang aral, pagmamahalan\n\nSiya’y ating ihayag at nang tumakas\nAng bumabagabag na si Satanas\nTulinan mo ang lakad dalhin ang hirap\nNang tunay nating malasap bihis na galak\n\nLapit na O! Bayan at makipisan\nSa aming awitan ng pagdiriwang\nPuri at paggalang kay Cristong ngalan\nMagpakailanma’y awit ang tanan","sourcePage":85},{"id":"hymn-086","number":86,"title":"PAG-ASA’Y TAGUMPAY","subtitle":"(Faith is the Victory)","lyrics":"Libot sa burol ng ilaw O Kristyanong tindig\nMagbaka bago dumilim matakpan ang sinag\nKaaway ang sanlibutan lakas ay ibigay\nPag-asa ay pagtagumpay laban nitong mundo\n\nKORO\nPag-asa’y tagumpay, pag-asa’y tagumpay\nLuwalhating tagumpay laban nitong mundo\n\nBandila N’ya ay pag-ibig salita N’ya tabak\nDaan ng banal ay atin sigaw ang tagumpay\nPag-asa ay mananalo buong sanlibutan\nPag-asa’y di mamamatay taglayin din natin\n\nLibot sa ating kaaway lalaban ng tunay\nIwaksi ang katamaran hayo at lumaban\nTurbante ng kaligtasan at katotohanan\nDaigdig ay manginginig sa ating pagsigaw\n\nS’yang manaig sa kalaban puting damit bigyan\nSa langit ay malalaman tanyag ang Pangalan\nHayo sa burol ng ilaw puso’y nagniningas\nTalo natin ang masama dahilan kay Jesus","sourcePage":86},{"id":"hymn-087","number":87,"title":"IBIG KONG ISALAYSAY","subtitle":"(I Love to Tell the Story)","lyrics":"Ibig kong isalaysay ang ukol sa langit\nAng lwalhati ni Cristo at Kanyang pag-ibig\nIbig kong isalaysay pagka’t ito’y tunay\nSa t’wing aking uliti’y ako’y nasis’yahan\n\nKORO\nIbig kong isalaysay ang lumang kasaysayang\nUkol sa pagmamahal ni Cristo sa tanan\n\nIbig kong isalaysay ang buhay ni Jesus\nNa puspos ng hiwaga lipos ng pag-ibig\nNais kong ‘yong malaman ang tanging dahilan\nBakit mahal sa akin ngalan Niyang banal\n\nIbig kong isalaysay nang iyong mabatid\nSa t’wing ulit uliti’y lalong tumatamis\nNais kong ibalita sa di na karinig\nAral ng kaligtasan buhay sa langit\n\nIbig kong ipahayag sa nakababatid\nKahit sila ay waring laging nauuhaw\nAt kung kayo’y umawit sa kalwalhatian\nAng lumang kasaysayan ang awit kong mahal","sourcePage":87},{"id":"hymn-088","number":88,"title":"DALHIN SILA KAY JESUS","subtitle":"(Bring Them In)","lyrics":"Tinig Niya’y naririnig\nSa malayo’t maligalig\nTupa Niyang nawawaglit\nTinatawag na lumapit\n\nKORO\nDalhin mo na sila upang mangaligtas sa sala\nDalhin mo na sila Kay Jesus ligaw na tupa\n\nSinong hahayo’t tutulong\nKay Jesus mabuting pastol\nSinong kukuha sa sahol\nUpang hindi malinggatong\n\nDaing nila ay pakinggan\nMula sa dakong mapanglaw\nTayo ay inuutusang\nHanapin ang Aking kawan","sourcePage":88},{"id":"hymn-089","number":89,"title":"IPAGDIWANG ANG ATING GAWAIN","subtitle":"(Battle Hymn of the Republic)","lyrics":"Tinig ng pag-aawitan ang siyang naririnig\nKawal ng katotohanan ang siyang nananaig\nSa larangan ng digmaang watawat ay pag-ibig\nHayo’t makisanib\n\nKORO\nLakad lakad wag umurong\nSi Jesus ang S’yang katulong\nLakad lakad hwag lumingon\nTagumpay mayroon\n\nHukbo ng kalalakihan ang siyang mangunguna\nSa lahat ng gawing nauukol sa Iglesiya\nAt ang kababaihan ang siyang pangalawa\nHayo’t makisanib\n\nPagtulungang itatag ang kaharian ni Jesus\nManga kawal ng sama’y piloting lansaging lubos\nAt nang upang lumaya kaluluwang binusabos\nHayo’t makihamok\n\nHalina kayo at sama-samang ating awitan\nIpagdiwang isigaw ang ating manga Gawain\nMakipaglabang matatag, matibay at mahinhin\nSi Cristo’y s’yang sundin","sourcePage":89},{"id":"hymn-090","number":90,"title":"DOON SA KRUS","subtitle":"(At The Cross)","lyrics":"Tunay dugo’y itinigis ng Haring nagtitis\nBuhay N’ya’y sadyang inalis ng taong bulisik\n\nKORO\nD’on sa krus, d’on sa krus Liwanag ay\nnamasdam\nAt ang tingib kong puso’y naibsan\nD’on ko natanggap aking katubusan\nMasaya ako kailanman\n\nDahil ba sa aking sala siya’y nahirapan\nSa awang walang kapantay pag-ibig N’ya’y\ntunay\n\nAng puso ko’y hinugasan ng dugo N’yang mahal\nAt sa kanya ihahandog ang buo kong buhay","sourcePage":90},{"id":"hymn-091","number":91,"title":"MGA ANGHEL NAG-AWITAN","subtitle":"(Hark, The Herald Angels Sing)","lyrics":"Manga anghel nag-awitan\nL’walhati sa Sumilang\nSa lupa’y kapayapaan\nDios at tao’y nagpisan\nBansa’y nangag-awitan\nManga Anghel ay Samahan\nKanilang sinasasay\nSi Cristo ay sumilang\n\nSinamba ng kalangitan\nAng Sugong walang hanggan\nManga bansa ay lapitan\nSa kanila’y tumahan\nNagkatawang tao ang Dios\nAt sa tao ay pumisan\nNagbigay kaaliwan\nJesus ang inginalan\n\nPuno ng kapayapaan!\nAt Araw ng kat’wiran\nNagbigay buhay at ilaw\nSa pakpak kanyang taglay\nL’walhati Kanyang iniwan\nAt sa tao ay pumisan\nUpang kalul’wa’y bigyan\nBuhay na walang hanggan","sourcePage":91},{"id":"hymn-092","number":92,"title":"HALINA! MGA MATATAPAT","subtitle":"(O Come, All Ye Faithful)","lyrics":"Lahat ng tapat ngayon ay magalak na’t\nHumayo sa bayan ng Betlehem\nLapit at masdan ang Haring bagong silang\n\nKORO\nAtin nga S’yang purihin Lapitan at igalang\nAt sambahin Siyang Panginoon\n\nO Anghel sa langit hayo’t magawitan\nPurihin ang Hari na dumatal\nL’walhati sa Dios sa kaitasan\n\nBinabati naming Haring bagong silang\nJesus, Iyo ang kaluwalhatian\nNahayag ka salama’t nakipamuhay","sourcePage":92},{"id":"hymn-093","number":93,"title":"MAG-AWITANG MAY KATUWAAN","subtitle":"(Joy To The World)","lyrics":"Mag awitang may kat’waan\nLahat ng nilalang\nSa Panginoon na marangal\nNa Hari ng tanan, na Hari ng tanan\nNa Hari, Na Hari ng tanan\n\nSanlibutan ay magsaya\nSa Tagapag-adya\nAwitin nang buong sigla\nKapurihan Niya, Kapurihan Niya\nKapurihan, kapurihan\n\nSiya nga ang kaaliwan\nNg makasalanan\nAt Siya tawagan lamang\nPala ay kakamtan\nPala ay kakamtan\nPala, pala ay kakamtan\n\nMundo ay paghaharian\nNg katotohanan\nAng biyaya’t kaligtasan\nKakamtan ng bayan\nKakamtan ng bayan\nKakamtan, kakamtan ng bayan","sourcePage":93},{"id":"hymn-094","number":94,"title":"BANAL, BANAL, BANAL","subtitle":"(Holy, Holy, Holy)","lyrics":"Kabanal banalan! Dios na Maalam\nMaaga ka naming pinapupurihan\nBatis ng Pag-ibig\n\nKabanal-banalan! Lahat Mong nilikha\nSa kataasan Mo’y nagpapakumbaba\nKahit manga anghel\n\nKabanal-banalan! Kahit ang karimlan\nO ang kasalana’y di makahahadlang\nSa’ming Pagkaalam\nKabanal-banalan, Makapangyarihan!\nPinapupurihan Ka ng ’yong nilalang\nLupa, langit, dagat","sourcePage":94},{"id":"hymn-095","number":95,"title":"SA MGA PANGAKO’Y UMASA","subtitle":"(Standing On The Promises)","lyrics":"Lahat ng pangako ng Dios na Ama\nTibay ko sa pananampalataya\nAng buhay ko’y nasa Liwanag niya\nLaging sa pangako’y naasa\n\nKORO\nLubha, Sagana, manga pangako ni Jesus na\nbiyaya\nLubha, Sagana, Ako sa tipan Niya’y tiwala\n\nAng pangako Niya sa taong tapat\nSa kabutihan ng Dios magaganap\nTiwala akong lagi at panatag\nNa tatamuhin ko ang galak\n\nLahat ng pangako ng Dios ay tapat\nTanglaw at lakas ng buhay kong angkin\nSiyang sa dalita’y katulong natin\nNang ang kasamaa’y gahisin","sourcePage":95},{"id":"hymn-096","number":96,"title":"ANG AMA AY PAPURIHAN","subtitle":"(Doxology)","lyrics":"Ang Ama ay papurihan\nAnak, Espiritung banal\nNg manga taong nilalang\nAt tanang kalangitan.\nAMEN.","sourcePage":96},{"id":"hymn-097","number":97,"title":"DAKILA KA","subtitle":"(How Great Thou Art)","lyrics":"O Haring Diyos, ang aking namamalas\nna kariktan ng sang nilikha mo;\nAraw, bituin, mga bundok at dagat\npatunay sa kapangyarihan mo.\n\nKORO\nKaya’t umaawit ang puso ko,\nnagpupuri, O Diyos sa iyo;\nDina-dakila ka ’t sinasamba;\nO Haring Diyos, dakila ka!\n\nKapag ako’y namamasyal sa parang,\npaghuni ng ibo’y naririnig;\nAt pagtanaw mula sa kabundukan,\nnadarama ang hanging kay lamig.\n\nHindi natin mauunawang tunay\ndakila niyang pag-ibig sa atin;\nDoon sa krus si Kristo’y nabayubay\nupang katuparan ay ating kamtin.\n\nBalang-araw, magbabalik si Kristo,\nat sa langit tayo’y isasama;\nWalang hanggang mag-aawitan tayo,\nihahayag kadakilaan niya.","sourcePage":97},{"id":"hymn-101","number":101,"title":"CONQUER OUR MISSION FIELD","subtitle":null,"lyrics":"with Tagalog\n\nWe are the disciples of Christ\nA generation of obeys His command\nWe will build all systems\nImprove Christian lives\nWe shall bless our people whom we serve\n\nChorus\nWe will conquer our mission field for Christ\nWe will go, we will fight the good fight of the faith\nWe will conquer our mission field for Christ\nWe will go, we will fight\nWe will suffer ‘till the end\nTo live is Christ and to die is gain\n\nTagalog\nKami’y iyong alagad\nIsang lahing sa utos mo’y tumutupad\nPatitibayin ang Iglesia\nItataas ang isa’t isa\nKabutihan mo’y ibabahagi sa madla\n\nKORO\nPanumbalikin ang lahat sayo Cristo\nTipunin ang lahat upang sumamba sa iyo\nKami’y hahayo at lalaban sa mundo\nHinding-hindi patatalo\nHandang maghirap hanggang dulo\nMamamatay nang naglilingkod sayo","sourcePage":101}];
